import { useCallback, useState } from 'react';

import type OpenFin from '@openfin/core';

import { createInlineDebugLogger } from '@common/utils/debug-log';
import { createZoomControlsDialogChannel } from '@common/utils/enterprise-channels';
import { getFocusedContents } from '@common/utils/getFocusedContents';
import { getClosestBoundsIfModalBoundsOffscreen } from '@common/utils/modal-bounds';
import { ZOOM_DIALOG_CHANNEL_ACTION, ZoomControlsDialogStateMessage } from '@common/utils/popup-window';
import { configurePopupParentIdentityLifecycle } from '@common/utils/popup-window/parentIdentityLifecycle';
import { usePopupChannel } from '@common/utils/popup-window/usePopupChannel';
import { WindowName } from '@common/utils/window';

import { useFocusManager } from '@common/hooks/useFocusManager';

import { useIsWindows } from './useIsWindows';

const logZoomDebug = createInlineDebugLogger('zoom-debug');

/**
 * Provider side for the zoom controls dialog window: channel lifecycle, SAAS-2980 parent binding,
 * and presenting the window at computed bounds.
 */
export const useZoomControlsDialogHost = () => {
    const { focusView } = useFocusManager();
    const [stateMessage, setStateMessage] = useState<ZoomControlsDialogStateMessage | null>(null);

    const isWindows = useIsWindows();
    usePopupChannel<ZoomControlsDialogStateMessage>({
        createChannel: createZoomControlsDialogChannel,
        actionName: ZOOM_DIALOG_CHANNEL_ACTION,
        handler: async (message) => {
            logZoomDebug('host:channel-message', {
                selectedView: message.payload?.selectedViewIdentity?.name,
                openedViaMouseClick: message.payload?.openedViaMouseClick,
                parentWindow: message.parentIdentity?.name
            });
            setStateMessage(message);
        }
    });

    const presentAtBounds = useCallback(
        async (bounds: OpenFin.Bounds, message: ZoomControlsDialogStateMessage) => {
            const zoomWindow = fin.Window.wrapSync({ name: WindowName.ZoomControlsDialog, uuid: fin.me.uuid });

            await configurePopupParentIdentityLifecycle(zoomWindow, message.parentIdentity, isWindows);

            const openedViaMouseClick = message.payload?.openedViaMouseClick ?? false;

            const win = fin.me as OpenFin.Window;
            logZoomDebug('host:present-start', {
                bounds,
                parentWindow: message.parentIdentity?.name,
                selectedView: message.payload?.selectedViewIdentity?.name,
                openedViaMouseClick
            });

            // always set bounds even if we are showing in case the modal was invoked
            // from another window
            await win.setBounds(await getClosestBoundsIfModalBoundsOffscreen(bounds));

            if (await win.isShowing()) {
                logZoomDebug('host:already-showing', {
                    selectedView: message.payload?.selectedViewIdentity?.name,
                    openedViaMouseClick
                });
                if (isWindows && message.payload.selectedViewIdentity && !openedViaMouseClick) {
                    const focusedIdentity = await getFocusedContents();
                    const isZoomDialogFocused = focusedIdentity?.name === WindowName.ZoomControlsDialog;
                    logZoomDebug('host:already-showing-focus-check', {
                        focusedContent: focusedIdentity?.name ?? null,
                        isZoomDialogFocused
                    });

                    // Windows-only edge case, if you quickly swap between windows while the dialog
                    // is showing, after using hotkeys you lose focus. This ensures the view
                    // retains focus so you can keep using hotkeys after the first invocation in the swapped window.
                    // Only do this when the zoom dialog is actually focused, so we don't steal focus
                    // from higher-priority interactions (e.g. address bar / search menu expansion).
                    if (isZoomDialogFocused) {
                        logZoomDebug('host:focus-view-on-already-showing', {
                            selectedView: message.payload.selectedViewIdentity.name
                        });
                        focusView(message.payload.selectedViewIdentity, 'programmatic');
                    }
                }
                return;
            }

            await win.show();
            logZoomDebug('host:show');
            await win.bringToFront();
            logZoomDebug('host:bring-to-front');

            if (openedViaMouseClick) {
                await win.focus();
                logZoomDebug('host:focus-window-mouse-open');
            }
        },
        [isWindows, focusView]
    );

    // NOTE: we don't need to dispatch anything back on dismiss, just clear the state
    const onDismiss = useCallback(() => setStateMessage(null), []);

    return { stateMessage, presentAtBounds, onDismiss };
};
